import json
from pathlib import Path

sources = json.loads(Path('source.json').read_text())
proposals = {}
def add(number, xml, reason, notes):
    assert number not in proposals
    proposals[number] = (xml, reason, notes)

transition_2026 = "La note source maintient l'entrée en vigueur au 26 mai 2026, six mois après la promulgation de la loi n° 2025-1129 du 26 novembre 2025, et exclut les procédures d'évolution des schémas de cohérence territoriale ou des plans locaux d'urbanisme en cours à cette date. Cette transition historique reste applicable ; elle ne fixe aucune date d'entrée en vigueur d'une réforme proposée."
transition_2021 = "La note source réserve cette rédaction aux schémas de cohérence territoriale, plans locaux d'urbanisme, documents en tenant lieu et cartes communales dont l'élaboration ou la révision est engagée à compter du 1er avril 2021, conformément à l'article 7 de l'ordonnance n° 2020-745 du 17 juin 2020. Ne pas l'étendre aux procédures antérieures."

add('L153-28', """<p>Lorsque le plan local d'urbanisme tient lieu de programme local de l'habitat, son évaluation porte aussi sur les résultats de son application au regard des objectifs prévus à l'article L. 302-1 du code de la construction et de l'habitation.</p>
<p>Si le plan ne répond pas aux objectifs définis à l'article L. 302-2 du code de la construction et de l'habitation, l'autorité administrative compétente de l'Etat peut, après la délibération prévue au deuxième alinéa de l'article L. 153-27, demander les modifications qu'elle estime nécessaires. L'établissement public de coopération intercommunale lui indique, dans un délai d'un mois, s'il entend procéder à ces modifications. A défaut d'accord, ou si aucune délibération n'approuve les modifications demandées dans un délai d'un an à compter de la demande de modifications, l'autorité administrative compétente de l'Etat engage la mise en compatibilité du plan.</p>""",
"Réécriture à droit constant : distinction de l'évaluation du volet habitat et de la procédure de modification demandée par l'Etat ; formulation explicite de la réponse de l'établissement public et des deux causes de mise en compatibilité. Aucune réforme de fond n'est introduite dans ce régime.",
"Incohérence préexistante : le renvoi au deuxième alinéa de L153-27 est conservé, mais le source_xml de L153-27 dans le corpus fourni situe la délibération sur l'opportunité de réviser le plan au troisième alinéa ; le deuxième traite des unités touristiques nouvelles et du recul du trait de côte. Une correction de ce renvoi appelle une coordination explicite. Délais conservés : un mois pour la réponse et un an à compter de la demande pour la délibération approuvant les modifications. Le point de départ du délai d'un mois n'est pas précisé dans la source. Les objectifs distincts de L302-1 et L302-2 du CCH et le contrôle de l'Etat demeurent applicables ; aucune convention locale ne les écarte.")

add('L153-29', """<p>Lorsque le plan local d'urbanisme tient lieu de programme local de l'habitat, l'organe délibérant de l'établissement public de coopération intercommunale établit un bilan de l'application des dispositions du plan relatives à l'habitat, au regard des objectifs prévus à l'article L. 302-1 du code de la construction et de l'habitation. Il établit ce bilan au plus tard trois ans après la délibération portant approbation ou révision du plan et le transmet à l'autorité administrative compétente de l'Etat. Tant que le plan n'a pas été mis en révision, ce bilan est renouvelé tous les trois ans.</p>""",
"Réécriture à droit constant : la phrase initiale est divisée pour identifier l'auteur du bilan, son objet, son échéance et sa transmission. La périodicité et sa condition de maintien sont exprimées séparément, sans réforme de fond.",
"Conserver le premier bilan au plus tard trois ans après la délibération d'approbation ou de révision et son renouvellement tous les trois ans tant que le plan n'a pas été mis en révision. Le bilan porte sur les seules dispositions relatives à l'habitat, appréciées au regard de L302-1 du CCH ; il ne se substitue pas aux autres évaluations du plan.")

add('L153-30', """<p>Lorsque le plan local d'urbanisme tient lieu de plan de mobilité, les évaluations et les calculs prévus à l'article L. 1214-8-1 du code des transports sont réalisés lors de l'élaboration du plan et lors de l'analyse de ses résultats prévue à l'article L. 153-27.</p>""",
"Réécriture à droit constant : les deux étapes auxquelles les évaluations et calculs doivent être réalisés sont rattachées directement à cette obligation. Le cumul de ces étapes et les deux renvois sont maintenus ; aucune réforme de fond.",
"La note source fixe l'entrée en vigueur de cette rédaction au 1er janvier 2021, conformément au XI de l'article 16 de la loi n° 2019-1428 du 24 décembre 2019. Cette date historique n'est pas celle d'une réforme proposée. Les évaluations et les calculs de L1214-8-1 du code des transports sont tous deux requis lors de l'élaboration et lors de l'analyse prévue à L153-27.")

add('L153-31', """<p>L'établissement public de coopération intercommunale ou la commune qui décide de changer les orientations définies par le projet d'aménagement et de développement durables révise le plan local d'urbanisme. Cette obligation de révision ne s'applique toutefois pas dans les cas mentionnés aux deuxième à cinquième alinéas de l'article L. 153-36 ni dans les autres cas prévus par la loi.</p>""",
"Réécriture à droit constant : l'autorité qui décide le changement des orientations devient le sujet de l'obligation de révision ; les exceptions sont isolées dans une seconde phrase. Aucun nouveau cas de révision ou de modification n'est créé.",
"Les deuxième à cinquième alinéas de L153-36 sont maintenus à leur place dans la proposition de cet article : les dérogations obligatoires et la faculté liée aux zones littorales restent distinctes. Les autres exceptions légales sont également conservées. " + transition_2026)

add('L153-32', """<p>L'organe délibérant de l'établissement public de coopération intercommunale ou le conseil municipal prescrit la révision par délibération.</p>""",
"Réécriture à droit constant par passage à la voix active : l'autorité compétente et la forme de la prescription de révision sont immédiatement identifiables. Aucune réforme de fond.",
"La compétence appartient à l'organe délibérant ou au conseil municipal, et non au seul président ou au maire. La prescription par délibération est conservée. Maintenir la coordination avec L153-33 pour le débat pouvant se tenir lors de la mise en révision.")

add('L153-33', """<p>La révision suit les modalités d'élaboration du plan local d'urbanisme définies à la section 3 du présent chapitre.</p>
<p>Le débat sur les orientations du projet d'aménagement et de développement durables prévu à l'article L. 153-12 peut toutefois se tenir lors de la mise en révision du plan local d'urbanisme.</p>
<p>Les communes intéressées par la révision sont consultées pour avis sur le projet de plan arrêté.</p>""",
"Réécriture à droit constant : maintien des trois alinéas, avec une formulation directe de la procédure suivie, de la faculté relative au débat et de la consultation des communes. Aucune réforme de fond.",
"Le renvoi à la section 3 reste général. La faculté de tenir le débat de L153-12 lors de la mise en révision ne supprime pas le débat. La consultation porte sur le projet arrêté et concerne toutes les communes intéressées par la révision.")

add('L153-35', """<p>Pendant la période comprise entre la mise en révision d'un plan local d'urbanisme et l'approbation de cette révision, une ou plusieurs modifications ou mises en compatibilité de ce plan peuvent être décidées.</p>""",
"Réécriture à droit constant : la période pendant laquelle d'autres évolutions du plan peuvent être décidées est placée en tête de phrase. La pluralité possible des modifications et des mises en compatibilité est conservée, sans réforme de fond.",
"Cette faculté ne dispense pas des procédures propres à chaque modification ou mise en compatibilité et ne crée aucune dérogation supplémentaire. Les deux bornes temporelles restent la mise en révision et l'approbation de cette révision. " + transition_2026)

add('L153-36', """<p>Le plan local d'urbanisme suit la procédure de modification prévue aux articles L. 153-37 à L. 153-44, sauf lorsqu'une révision s'impose en application de l'article L. 153-31.</p>
<p>Par dérogation à l'article L. 153-31, cette procédure de modification s'applique également aux changements des orientations du projet d'aménagement et de développement durables qui ont pour objet :</p>
<p>1° De soutenir le développement de la production d'énergie renouvelable, au sens de l'article L. 211-2 du code de l'énergie, de la production d'hydrogène renouvelable ou bas-carbone, au sens de l'article L. 811-1 du même code, ou du stockage d'électricité, ou d'identifier des zones d'accélération pour l'implantation d'installations terrestres de production d'énergies renouvelables mentionnées à l'article L. 141-5-3 du même code. La commission départementale de préservation des espaces naturels, agricoles et forestiers est saisie pour avis dans les conditions prévues à l'article L. 112-1-1 du code rural et de la pêche maritime ;</p>
<p>2° De délimiter, en application de l'article L. 151-14-1 du présent code, des secteurs dans lesquels les constructions nouvelles de logements ou les logements issus de la transformation de bâtiments dont la destination n'est pas l'habitation sont exclusivement à usage de résidence principale, au sens de l'article 2 de la loi n° 89-462 du 6 juillet 1989 tendant à améliorer les rapports locatifs et portant modification de la loi n° 86-1290 du 23 décembre 1986.</p>
<p>Si l'autorité compétente le décide, la procédure de modification peut aussi s'appliquer aux changements des orientations du projet d'aménagement et de développement durables qui ont pour objet de délimiter les zones mentionnées à l'article L. 121-22-3 du présent code.</p>""",
"Réécriture à droit constant : formulation plus directe de la règle générale, des deux dérogations imposant la procédure de modification et de la dérogation laissée au choix de l'autorité compétente. La consultation de la commission et tous les champs énergétiques, résidentiels et littoraux sont maintenus ; aucune réforme de fond nouvelle.",
"Cinq alinéas conservés dans le même ordre pour préserver le renvoi de L153-31 aux deuxième à cinquième alinéas. Maintenir les 1° et 2°, l'hydrogène renouvelable ou bas-carbone, le stockage d'électricité, les zones d'accélération, l'avis de la commission et l'usage exclusif de résidence principale. L151-14-1 et L121-22-3 sont conservés sans élargir leurs conditions propres. Les orientations de densification de policy.json ne justifient pas une nouvelle dérogation générale à la révision dans cet article. " + transition_2026)

add('L153-37', """<p>Le président de l'établissement public de coopération intercommunale ou le maire prend l'initiative de la procédure de modification et établit le projet de modification.</p>""",
"Réécriture à droit constant : la même autorité est explicitement sujet de l'initiative de la procédure et de l'établissement du projet. Aucune réforme de fond.",
"Ne pas confondre cette initiative du président ou du maire avec la prescription de la révision par délibération prévue à L153-32. La procédure de L153-41 conserve ses règles particulières lorsque l'initiative émane du maire d'une commune membre et ne porte que sur son territoire.")

add('L153-38', """<p>Lorsque le projet de modification porte sur l'ouverture d'une zone à l'urbanisation, l'organe délibérant de l'établissement public compétent ou le conseil municipal adopte une délibération motivée justifiant l'utilité de cette ouverture. Cette justification tient compte des capacités d'urbanisation encore inexploitées dans les zones déjà urbanisées ainsi que de la faisabilité opérationnelle d'un projet dans ces zones.</p>""",
"Réécriture à droit constant : l'auteur de la délibération et l'obligation de motivation sont explicités ; les deux éléments d'appréciation sont regroupés dans une phrase distincte. Aucune réforme de fond ni dispense d'examen des zones déjà urbanisées.",
"Les capacités encore inexploitées et la faisabilité opérationnelle d'un projet doivent toutes deux être appréciées dans les zones déjà urbanisées. Coordination avec le diagnostic de L151-4 et les enveloppes de densification de L151-26 retenus dans coordination.json : ces dispositions n'effacent pas l'exigence de motivation du présent article.")

add('L153-39', """<p>Si le projet de modification a pour objet ou pour effet de modifier les règles d'urbanisme applicables dans le périmètre d'une zone d'aménagement concerté créée à l'initiative d'une personne publique autre que l'établissement public de coopération intercommunale ou la commune, le plan local d'urbanisme modifié ne peut être approuvé qu'après avis de cette personne publique.</p>
<p>Si la zone d'aménagement concerté a été créée à l'initiative d'un établissement public de coopération intercommunale, l'approbation du plan modifié exige un avis favorable de cet établissement.</p>""",
"Réécriture à droit constant : les deux alinéas expriment directement les conditions préalables à l'approbation. La distinction entre avis requis et avis obligatoirement favorable est maintenue, sans réforme de fond.",
"Le premier alinéa vise tant l'objet que l'effet du projet de modification et conserve la condition relative à l'identité de la personne publique à l'initiative de la zone. Le second conserve l'exigence spéciale d'un avis favorable de l'établissement public de coopération intercommunale ; ne pas réduire cet avis à une consultation simple.")

add('L153-40', """<p>Le président de l'établissement public de coopération intercommunale ou le maire notifie le projet de modification aux personnes publiques associées mentionnées aux articles L. 132-7 et L. 132-9 avant l'ouverture de l'enquête publique ou avant la mise à disposition du projet au public.</p>
<p>Le projet de modification est aussi notifié aux maires des communes concernées.</p>""",
"Réécriture à droit constant : l'auteur et les destinataires de la notification précèdent son échéance ; la notification aux maires reste dans un alinéa distinct. Aucune réforme de fond.",
"Les deux catégories de destinataires et les renvois à L132-7 et L132-9 sont conservés. Lacune de coordination préexistante à contrôler : L153-41 prévoit aussi une participation du public par voie électronique, tandis que le présent article ne mentionne expressément comme échéances que l'ouverture de l'enquête publique ou la mise à disposition du public. Cette troisième modalité n'est pas ajoutée silencieusement au texte.")

add('L153-40-1', """<p>Lors de la notification du projet de modification prévue à l'article L. 153-40, le représentant de l'Etat communique, s'il y a lieu, sa position à la commune ou au groupement de communes compétent qui en fait la demande. Cette position porte sur les points suivants :</p>
<p>1° Le cas échéant, la sincérité de l'analyse de la consommation d'espaces naturels, agricoles et forestiers réalisée dans le diagnostic du rapport de présentation prévu à l'article L. 151-4 ;</p>
<p>2° Le cas échéant, la cohérence, avec le diagnostic mentionné au 1° du présent article, des objectifs chiffrés de modération de la consommation de l'espace et de lutte contre l'étalement urbain contenus dans le projet d'aménagement et de développement durables en application de l'article L. 151-5.</p>""",
"Réécriture à droit constant : les conditions de demande, le moment de la communication et les deux objets de la position de l'Etat sont présentés directement. Les réserves « s'il y a lieu » et « le cas échéant » sont maintenues ; aucune réforme de fond.",
"Maintenir les subdivisions 1° et 2° et leur lien : la cohérence des objectifs chiffrés s'apprécie au regard du diagnostic visé au 1°. La position de l'Etat intervient sur demande et ne vaut pas approbation automatique du projet. La coordination déjà retenue pour L151-4 doit préserver l'analyse de la consommation d'espaces naturels, agricoles et forestiers ; L151-5 et les objectifs chiffrés restent visés.")

add('L153-41', """<p>I. - La mise à disposition du public du projet de modification est assurée soit par le président de l'établissement public de coopération intercommunale ou le maire d'une commune membre de cet établissement si la modification ne concerne que le territoire de cette commune, soit par le maire dans les autres cas. Le maire ou le président de l'établissement public de coopération intercommunale peut remplacer cette mise à disposition par une procédure de participation du public au sens de l'article L. 123-19 du code de l'environnement ou par une enquête publique.</p>
<p>Si le projet de modification est soumis à une évaluation environnementale en application de l'article L. 104-1 du présent code, une participation du public par voie électronique ou une enquête publique doit être organisée.</p>
<p>Si la modification ne concerne que certaines communes, la mise à disposition, la procédure de participation du public par voie électronique ou l'enquête publique peut être organisée sur le seul territoire de ces communes.</p>
<p>II. - Pendant un mois, le projet de modification, l'exposé de ses motifs et, le cas échéant, les avis des personnes publiques associées mentionnées aux articles L. 132-7 et L. 132-9 sont mis à la disposition du public dans des conditions qui lui permettent de formuler des observations. Ces observations sont enregistrées et conservées.</p>
<p>L'organe délibérant de l'établissement public compétent ou le conseil municipal, selon le cas, précise les modalités de la mise à disposition. Lorsque le projet procède de l'initiative du maire d'une commune membre et ne porte que sur le territoire de celle-ci, l'organe délibérant de l'établissement public précise ces modalités dans un délai de trois mois à compter de la transmission du projet à l'établissement public. Ces modalités sont portées à la connaissance du public au moins huit jours avant le début de la mise à disposition.</p>
<p>A l'issue de la mise à disposition, le président de l'établissement public ou le maire en présente le bilan devant l'organe délibérant de l'établissement public ou le conseil municipal. Celui-ci délibère sur ce bilan et adopte, par délibération motivée, le projet éventuellement modifié pour tenir compte des avis émis et des observations du public. Lorsque le projet de modification procède de l'initiative du maire d'une commune membre et ne porte que sur son territoire, ce maire présente le bilan de la mise à disposition devant l'organe délibérant de l'établissement public. Cet organe délibère sur le projet dans un délai de trois mois à compter de cette présentation.</p>
<p>III. - L'enquête publique prévue au I du présent article est conduite conformément au chapitre III du titre II du livre Ier du code de l'environnement.</p>
<p>Les avis des personnes publiques associées mentionnées aux articles L. 132-7 et L. 132-9 du présent code sont joints au dossier d'enquête publique ou, le cas échéant, soumis à la procédure de participation du public par voie électronique.</p>
<p>En cas de participation du public par voie électronique, le dossier est aussi mis en consultation sur un support papier dans les mairies concernées, pendant leurs horaires d'ouverture.</p>""",
"Réécriture à droit constant : maintien des I, II et III et des neuf alinéas, avec des phrases distinctes pour les obligations de participation, les modalités de mise à disposition, le bilan et les décisions. Les délais, les trois voies de participation, la consultation papier et les règles propres à l'initiative d'un maire d'une commune membre sont conservés. Aucune réforme de fond nouvelle.",
"Ambiguïté préexistante conservée au premier alinéa : la construction « soit par le président [...] ou le maire [...] si la modification ne concerne que [...] cette commune, soit par le maire dans les autres cas » laisse incertaine l'organisation des modifications intercommunales portant sur plusieurs communes. Une clarification de compétence exige une coordination expresse, notamment avec L153-37. Articulation à contrôler entre l'adoption par délibération motivée au troisième alinéa du II et l'approbation prévue à L153-43 ; les deux prescriptions sont conservées. Pour la participation électronique, contrôler aussi la coordination des notifications de L153-40. Délais conservés : un mois de mise à disposition, trois mois après transmission du projet pour fixer ses modalités dans le cas communal particulier, information au moins huit jours avant son début et trois mois après présentation du bilan pour délibérer dans ce même cas. Les neuf alinéas et tous les renvois sont préservés. " + transition_2026)

add('L153-43', """<p>Après la mise à disposition du public, l'enquête publique ou la participation du public par voie électronique, l'organe délibérant de l'établissement public de coopération intercommunale ou le conseil municipal approuve le projet de modification par délibération. Le projet peut, avant cette approbation, être modifié pour tenir compte des avis joints au dossier, des observations du public et du rapport du commissaire ou de la commission d'enquête.</p>""",
"Réécriture à droit constant : la décision d'approbation est formulée à la voix active et les éléments susceptibles de justifier une modification du projet sont réunis dans une seconde phrase. Les trois modes de participation et toutes les catégories de contributions sont conservés, sans réforme de fond.",
"L'approbation demeure postérieure à la procédure de participation applicable. La possibilité de tenir compte des avis, observations et du rapport d'enquête concerne le projet soumis à cette approbation. Articulation préexistante à contrôler avec L153-41, II, qui prévoit déjà l'adoption du projet par délibération motivée après la mise à disposition ; aucune de ces étapes n'est supprimée. " + transition_2026)

add('L153-44', """<p>L'acte qui approuve une modification devient exécutoire une fois remplies les conditions définies aux articles L. 153-23 à L. 153-26.</p>""",
"Réécriture à droit constant : la subordonnée identifie directement l'acte concerné et rattache son caractère exécutoire à l'accomplissement des conditions auxquelles le code renvoie. Aucune réforme de fond.",
"La plage de renvoi L153-23 à L153-26 est conservée telle quelle, y compris les règles de publication, de transmission et les éventuels obstacles au caractère exécutoire qu'elle comporte. Aucun nouveau délai n'est créé. " + transition_2026)

add('L153-49', """<p>L'autorité administrative compétente de l'Etat informe l'établissement public de coopération intercommunale ou la commune lorsque le plan local d'urbanisme doit être rendu compatible avec un document mentionné aux articles L. 131-4, L. 131-5, L. 131-6 ou L. 131-8, ou prendre ce document en compte. Elle l'informe également lorsque le plan doit permettre la réalisation d'un projet d'intérêt général postérieur à l'approbation du plan.</p>""",
"Réécriture à droit constant : l'obligation d'information est placée sous la responsabilité explicite de l'Etat ; le cas du projet d'intérêt général est distingué de ceux concernant les documents supérieurs. La compatibilité et la prise en compte demeurent distinctes, sans réforme de fond.",
"Les quatre renvois L131-4, L131-5, L131-6 et L131-8 sont maintenus sans assimiler compatibilité et prise en compte. Le projet d'intérêt général doit rester postérieur à l'approbation du plan. " + transition_2021)

add('L153-50', """<p>L'autorité administrative compétente de l'Etat adresse à l'établissement public de coopération intercommunale compétent ou à la commune un dossier exposant les motifs pour lesquels elle estime que le plan local d'urbanisme ne respecte pas les obligations de mise en compatibilité et de prise en compte mentionnées aux articles L. 131-4, L. 131-5, L. 131-6 ou L. 131-8. Ce dossier indique aussi les modifications qu'elle estime nécessaires pour respecter ces obligations.</p>""",
"Réécriture à droit constant : deux phrases distinguent les motifs de l'intervention de l'Etat des modifications qu'il demande, avec un sujet grammatical cohérent. Les obligations visées et les destinataires sont conservés ; aucune réforme de fond.",
"Le dossier doit comporter à la fois les motifs de non-respect des obligations et les modifications estimées nécessaires. Les renvois aux quatre articles L131-4 à L131-6 et L131-8 sont maintenus ; ne pas étendre cet article à des obligations absentes de ces textes. " + transition_2021)

add('L153-51', """<p>Dans un délai d'un mois, l'établissement public de coopération intercommunale ou la commune indique à l'autorité administrative compétente de l'Etat s'il entend apporter la modification nécessaire suivant la procédure prévue à l'article L. 131-7.</p>
<p>L'autorité administrative compétente de l'Etat engage et approuve la mise en compatibilité du plan si aucun accord sur l'engagement de la procédure de modification n'intervient dans ce délai. Elle fait de même si, en cas d'accord, aucune délibération approuvant la modification du plan n'est intervenue à l'expiration d'un délai de six mois à compter de sa notification initiale.</p>""",
"Réécriture à droit constant : les deux hypothèses de substitution de l'Etat sont exprimées séparément, après l'obligation de réponse de la collectivité. Le renvoi à L131-7 et les délais d'un et de six mois restent inchangés ; aucune réforme de fond.",
"Le délai de six mois court à compter de la notification initiale de l'autorité de l'Etat et non de l'accord ou de l'expiration du délai d'un mois. La source n'explicite pas, au premier alinéa, le point de départ du délai d'un mois : cette imprécision n'est pas corrigée en ajoutant une règle. L131-7 renvoie, pour le PLU, à la procédure des articles L153-36 à L153-44 dans le corpus fourni. " + transition_2026)

add('L153-52', """<p>L'Etat, l'établissement public de coopération intercommunale compétent ou la commune, et les personnes publiques associées mentionnées aux articles L. 132-7 et L. 132-9 examinent conjointement la mise en compatibilité du plan.</p>""",
"Réécriture à droit constant : les participants deviennent les sujets de l'examen conjoint, ce qui rend explicite la participation de chaque catégorie. Le champ de l'examen et les renvois sont conservés ; aucune réforme de fond.",
"L'examen associe l'Etat, la collectivité compétente et les personnes publiques associées de L132-7 et L132-9. Ne pas confondre cet examen conjoint avec l'enquête publique de L153-53, ni avec la procédure propre aux opérations de L153-54 et suivants.")

