assert len(sources) == len(proposals) == 24
assert {x['number'] for x in sources} == set(proposals)
answer = []
for source in sources:
    xml, reason, notes = proposals[source['number']]
    row = {key: source[key] for key in ('code_id','source_id','source_sha256','number')}
    row.update(proposed_xml=xml, reason=reason, review_notes=notes, status='rewrite_draft')
    answer.append(row)
Path('answer.json').write_text(json.dumps(answer, ensure_ascii=False, indent=2) + '\n')
print(f'answer.json : {len(answer)} articles, {sum(len(x["proposed_xml"]) for x in answer)} caractères de propositions')
